use base64::{Engine as _,engine::general_purpose::STANDARD};
use ed25519_dalek::{Signer,SigningKey};
use floatboard_core::update::{self,Manifest,UpdateService};
use serde_json::json;
fn fixture()->Manifest{Manifest{schema:1,version:"1.2.0".into(),platform:"windows-x86_64".into(),minimum_version:"0.8.0".into(),updater_protocol:1,data_compatibility:"backward-compatible".into(),url:"https://github.com/Memento1990/codex-task/releases/download/v1.2.0/Floatboard.zip".into(),size:123,sha256:"ab".repeat(32)}}
fn signed(manifest:&Manifest)->(Vec<u8>,String,String){let key=SigningKey::from_bytes(&[42u8;32]);let bytes=serde_json::to_vec(manifest).unwrap();let signature=STANDARD.encode(key.sign(&bytes).to_bytes());(bytes,signature,STANDARD.encode(key.verifying_key().to_bytes()))}
#[test]fn valid_manifest_accepts_only_verified_forward_compatible_stable_update(){let(bytes,sig,key)=signed(&fixture());assert_eq!(update::verify_manifest_with_key(&bytes,&sig,&key,"0.9.0").unwrap(),fixture());}
#[test]fn altered_signature_key_or_bytes_is_rejected(){let(mut bytes,sig,key)=signed(&fixture());bytes.push(b' ');assert!(update::verify_manifest_with_key(&bytes,&sig,&key,"0.9.0").is_err());let(bytes,_,_)=signed(&fixture());assert!(update::verify_manifest_with_key(&bytes,&STANDARD.encode([0;64]),&key,"0.9.0").is_err());assert!(update::verify_manifest_with_key(&bytes,&sig,&STANDARD.encode([1;32]),"0.9.0").is_err());}
#[test]fn unsupported_schema_platform_protocol_data_and_minimum_fail_closed(){for mutation in 0..8{let mut manifest=fixture();match mutation{0=>manifest.schema=2,1=>manifest.platform="linux-x86_64".into(),2=>manifest.updater_protocol=2,3=>manifest.data_compatibility="breaking".into(),4=>manifest.minimum_version="1.0.0".into(),5=>manifest.version="1.2.0-beta.1".into(),6=>manifest.size=1024*1024*1024,_=>manifest.sha256="not-a-hash".into()}let(bytes,sig,key)=signed(&manifest);assert!(update::verify_manifest_with_key(&bytes,&sig,&key,"0.9.0").is_err(),"{mutation}");}}
#[test]fn downgrade_same_version_and_mismatched_asset_version_are_rejected(){let(bytes,sig,key)=signed(&fixture());for current in ["1.2.0","2.0.0"]{assert!(update::verify_manifest_with_key(&bytes,&sig,&key,current).is_err());}let mut manifest=fixture();manifest.url=manifest.url.replace("v1.2.0","v1.3.0");let(bytes,sig,key)=signed(&manifest);assert!(update::verify_manifest_with_key(&bytes,&sig,&key,"0.9.0").is_err());}
#[test]fn arbitrary_hosts_repo_credentials_ports_and_ambiguous_paths_rejected(){for url in ["http://github.com/Memento1990/codex-task/releases/download/v1/a.zip","https://github.com.evil.test/Memento1990/codex-task/releases/download/v1/a.zip","https://github.com/other/project/releases/download/v1/a.zip","https://user@github.com/Memento1990/codex-task/releases/download/v1/a.zip","https://github.com:444/Memento1990/codex-task/releases/download/v1/a.zip","https://github.com/Memento1990/codex-task/releases/download/v1/a.zip?url=evil","https://github.com/Memento1990/codex-task/releases/download/v1/%2fetc"]{assert!(!update::release_url(url),"{url}");}}
#[test]fn unknown_or_duplicate_manifest_fields_are_rejected_after_signature_verification(){let key=SigningKey::from_bytes(&[42;32]);let mut value=serde_json::to_value(fixture()).unwrap();value["execute"]=json!("evil");let bytes=serde_json::to_vec(&value).unwrap();assert!(update::verify_manifest_with_key(&bytes,&STANDARD.encode(key.sign(&bytes).to_bytes()),&STANDARD.encode(key.verifying_key().to_bytes()),"0.9.0").is_err());let source=String::from_utf8(serde_json::to_vec(&fixture()).unwrap()).unwrap().replacen("{","{\"schema\":1,",1);let bytes=source.as_bytes();assert!(update::verify_manifest_with_key(bytes,&STANDARD.encode(key.sign(bytes).to_bytes()),&STANDARD.encode(key.verifying_key().to_bytes()),"0.9.0").is_err());}
#[test]fn isolated_preferences_persist_and_unsigned_build_is_explicitly_unsupported(){let root=std::env::temp_dir().join(format!("floatboard-update-{}",uuid::Uuid::new_v4().simple()));let service=UpdateService::new(root.clone());assert_eq!(service.snapshot()["preferences"]["auto_download"],true);service.preferences(&json!({"auto_check":false,"auto_download":false})).unwrap();assert_eq!(UpdateService::new(root.clone()).snapshot()["preferences"]["auto_check"],false);assert!(service.preferences(&json!({"auto_check":"yes"})).is_err());if option_env!("FLOATBOARD_UPDATE_PUBLIC_KEY").is_none(){assert_eq!(service.snapshot()["supported"],false);assert_eq!(service.snapshot()["state"],"unsupported");assert!(service.check().is_err());assert!(service.begin_install().is_err());}std::fs::remove_dir_all(root).unwrap();}
